#!/usr/bin/env node
// Extract every model-visible tool schema from the official generated catalog
// (official-dsh/docs/tool-catalog.md) into a machine-readable fixture.
//
// The catalog is generated by `scripts/gen-tool-catalog.ts`, which BOOTS each tool
// plugin on a real Cordis context and reads ctx.tools.schemas(). That makes it the
// authoritative source for conformance standard #1 (byte-identical tool schema).
//
// Usage: node Tools/extract-tool-catalog.mjs <repo-root> <out.json>

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const [, , srcArg, outArg] = process.argv;
if (!srcArg || !outArg) {
  console.error('usage: extract-tool-catalog.mjs <docs/tool-catalog.md> <out.json>');
  process.exit(2);
}
const src = resolve(srcArg);
const out = resolve(outArg);
const text = readFileSync(src, 'utf8');
const lines = text.split('\n');

/** Tool Package Map rows: | `pkg` | `a`, `b` | ... | */
const rows = [];
for (const line of lines) {
  if (!line.startsWith('| `@deepseek-ai/')) continue;
  const cells = line.split('|').map((c) => c.trim());
  // cells[0] is empty (leading pipe)
  const pkg = cells[1]?.replace(/`/g, '');
  if (!pkg) continue;
  const names = [...(cells[2] ?? '').matchAll(/`([^`]+)`/g)].map((m) => m[1]);
  rows.push({ package: pkg, names });
}

/** Detailed sections: `## \`pkg\`` followed by `### \`tool\`` + description + json block. */
const tools = [];
let currentPackage = null;
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const pkgMatch = /^##\s+`(@deepseek-ai\/[^`]+)`\s*$/.exec(line);
  if (pkgMatch) {
    currentPackage = pkgMatch[1];
    continue;
  }
  const toolMatch = /^###\s+`([^`]+)`\s*$/.exec(line);
  if (!toolMatch) continue;
  const name = toolMatch[1];
  // Collect the description paragraph(s) until the opening fence.
  let j = i + 1;
  const descLines = [];
  while (j < lines.length && !lines[j].startsWith('```')) {
    if (/^###?\s/.test(lines[j])) break;
    descLines.push(lines[j]);
    j++;
  }
  let schema = null;
  if (j < lines.length && lines[j].startsWith('```json')) {
    const start = j + 1;
    let end = start;
    while (end < lines.length && !lines[end].startsWith('```')) end++;
    const raw = lines.slice(start, end).join('\n');
    try {
      schema = JSON.parse(raw);
    } catch (err) {
      console.error(`!! failed to parse schema for ${name}: ${err.message}`);
    }
    j = end;
  }
  tools.push({
    package: currentPackage,
    name,
    description: descLines.join('\n').trim().replace(/\s*\n\s*/g, '\n'),
    parameters: schema,
  });
  i = j;
}

// The map table lists model-visible names; use it to complete descriptions for any
// tool whose section is only present under an alias.
const byName = new Map();
for (const t of tools) {
  if (!byName.has(t.name)) byName.set(t.name, t);
}

const payload = {
  generatedBy: 'Tools/extract-tool-catalog.mjs',
  source: 'official-dsh/docs/tool-catalog.md',
  note: 'Model-visible tool schemas, booted from ctx.tools.schemas() by the official generator.',
  packageMap: rows,
  toolCount: byName.size,
  tools: [...byName.values()],
};

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, JSON.stringify(payload, null, 2));

const missingSchema = payload.tools.filter((t) => !t.parameters);
console.log(`packages: ${rows.length}`);
console.log(`tools with schema: ${byName.size}`);
console.log(`tools missing schema: ${missingSchema.length}${missingSchema.length ? ' -> ' + missingSchema.map((t) => t.name).join(', ') : ''}`);
console.log(`wrote ${out}`);
